#!/usr/bin/env python3
from __future__ import annotations
import html,json
from collections import Counter
from datetime import datetime,timezone
from pathlib import Path
from typing import Any

DOMAIN="https://estrechoormuz.com"

def load(path:Path,default:Any)->Any:
    try:return json.loads(path.read_text(encoding="utf-8"))
    except (OSError,json.JSONDecodeError):return default

def esc(v:Any)->str:return html.escape(str(v or "—"),quote=True)

def parse(v:Any):
    try:return datetime.fromisoformat(str(v).replace("Z","+00:00"))
    except Exception:return None

def rows(history):
    out=[]
    for item in history if isinstance(history,list) else []:
        if isinstance(item,dict):out.append(item)
    return out

def build(root:Path,lang:str)->str:
    history=rows(load(root/"history.json",[]));status=load(root/"status.json",{})
    states=Counter(str(i.get("status") or "UNKNOWN") for i in history)
    operations=Counter(str(i.get("operational_status") or "UNKNOWN") for i in history)
    confidence=Counter(str(i.get("confidence") or "UNKNOWN") for i in history)
    dates=[parse(i.get("at")) for i in history];dates=[d for d in dates if d]
    first=min(dates).strftime("%Y-%m-%d") if dates else "—";last=max(dates).strftime("%Y-%m-%d") if dates else "—"
    total=len(history); uncertain=states.get("INCIERTO",0); open_n=states.get("ABIERTO",0); closed=states.get("CERRADO",0)
    pct=lambda n:round((n/total*100),1) if total else 0
    es=lang=="es"
    title="Datos propios del monitor: historial, estados y confianza" if es else "Original monitor data: history, states and confidence"
    desc="Informe generado automáticamente desde history.json y status.json. No estima tráfico físico; describe las clasificaciones publicadas por el monitor." if es else "Report generated automatically from history.json and status.json. It does not estimate physical traffic; it describes classifications published by the monitor."
    nav='''<header class="site-header"><div class="header-inner"><a class="brand brand-v4" href="/index.html"><span class="brand-copy"><strong>ESTRECHO ORMUZ</strong><small>Inteligencia marítima y energética</small></span></a><nav class="site-nav"><a href="/index.html">Estado</a><a href="/analisis.html">Análisis</a><a href="/investigacion.html">Investigación</a><a href="/metodologia.html">Metodología</a></nav><a class="language-link" href="/en-monitor-original-data-report.html">EN</a></div></header>''' if es else '''<header class="site-header"><div class="header-inner"><a class="brand brand-v4" href="/en.html"><span class="brand-copy"><strong>HORMUZ STRAIT</strong><small>Maritime and energy intelligence</small></span></a><nav class="site-nav"><a href="/en.html">Status</a><a href="/en-analysis.html">Analysis</a><a href="/en-research.html">Research</a><a href="/en-methodology.html">Methodology</a></nav><a class="language-link" href="/datos-propios-monitor-ormuz.html">ES</a></div></header>'''
    cards=(f'<div class="a6-stat"><b>{total}</b><span>{"cambios significativos archivados" if es else "archived material changes"}</span></div><div class="a6-stat"><b>{pct(uncertain)}%</b><span>{"entradas publicadas como inciertas" if es else "entries published as uncertain"}</span></div><div class="a6-stat"><b>{len(operations)}</b><span>{"categorías operativas observadas" if es else "observed operational categories"}</span></div>')
    chart=f'<div class="a6-chart"><h2>{"Distribución de estados archivados" if es else "Distribution of archived states"}</h2><div class="a6-bar-row"><span>{"Incierto" if es else "Uncertain"}</span><div class="a6-bar-track"><div class="a6-bar is-amber" style="width:{pct(uncertain)}%"></div></div><strong>{uncertain}</strong></div><div class="a6-bar-row"><span>{"Abierto" if es else "Open"}</span><div class="a6-bar-track"><div class="a6-bar" style="width:{pct(open_n)}%"></div></div><strong>{open_n}</strong></div><div class="a6-bar-row"><span>{"Cerrado" if es else "Closed"}</span><div class="a6-bar-track"><div class="a6-bar is-red" style="width:{pct(closed)}%"></div></div><strong>{closed}</strong></div></div>'
    op_rows=''.join(f'<tr><td>{esc(k)}</td><td>{v}</td><td>{pct(v)}%</td></tr>' for k,v in operations.most_common()) or '<tr><td colspan="3">—</td></tr>'
    conf_rows=''.join(f'<tr><td>{esc(k)}</td><td>{v}</td><td>{pct(v)}%</td></tr>' for k,v in confidence.most_common()) or '<tr><td colspan="3">—</td></tr>'
    note=("Este conjunto mide decisiones publicadas, no número de buques. Un cambio puede producirse por nueva evidencia, una corrección metodológica o el vencimiento de una confirmación." if es else "This dataset measures published decisions, not vessel counts. A change can result from new evidence, a methodological correction or expiry of a confirmation.")
    method=("Los valores se calculan en cada ejecución a partir de archivos públicos. El informe muestra todos los cambios significativos conservados en history.json; no rellena periodos sin cambio ni infiere actividad marítima." if es else "Values are calculated on every run from public files. The report covers all material changes retained in history.json; it does not fill periods without change or infer maritime activity.")
    interpretation=("""<h2>Qué aporta este conjunto de datos</h2><p>El historial permite estudiar cómo se comporta el propio observatorio: cuántas veces publicó incertidumbre, qué categorías operativas utilizó y con qué confianza. Esa información ayuda a detectar si el sistema tiende a mantener estados anteriores, si corrige falsos positivos y si distingue riesgo de cierre efectivo.</p><p>Las entradas no representan intervalos de tiempo iguales. Una fila se guarda cuando existe un cambio material o una actualización que merece conservarse; por tanto, contar filas no equivale a medir cuántas horas permaneció cada estado. Para calcular duración sería necesario reconstruir intervalos entre marcas temporales y considerar el final del periodo observado.</p><h2>Cómo reproducir los resultados</h2><p>Las tablas se generan directamente desde <code>history.json</code>. Cada fila aporta estado, categoría operativa, confianza y fecha. El script agrupa los valores con un contador, divide cada grupo por el total de entradas archivadas y redondea la proporción a una cifra decimal. El estado vigente y la última comprobación proceden de <code>status.json</code>.</p><p>Los archivos fuente están enlazados y pueden descargarse sin registro. El código no añade estimaciones ocultas ni completa datos ausentes. Si una entrada carece de categoría, aparece como desconocida en vez de asignarse a la más probable.</p><h2>Limitaciones que deben respetarse</h2><p>Este informe no demuestra cuántos buques cruzaron, cuánto petróleo se transportó ni cuánto duró una interrupción física. Tampoco evalúa por sí solo la exactitud de cada noticia. Es un conjunto de datos editoriales sobre las decisiones publicadas por el monitor. Su valor está en la trazabilidad y en permitir una auditoría independiente del proceso de clasificación.</p>""" if es else """<h2>What this dataset adds</h2><p>The archive makes it possible to study the observatory itself: how often it published uncertainty, which operational categories it used and what confidence it assigned. That helps reveal whether the system tends to preserve old states, whether false positives are corrected and whether risk is kept separate from an effective closure.</p><p>Entries do not represent equal time intervals. A row is retained when a material change or a noteworthy update occurs, so counting rows is not the same as measuring how many hours each state lasted. Duration analysis would require rebuilding intervals between timestamps and defining the end of the observation period.</p><h2>How to reproduce the results</h2><p>The tables are generated directly from <code>history.json</code>. Each row supplies a state, operational category, confidence level and timestamp. The script groups values with counters, divides each group by the number of archived entries and rounds the share to one decimal place. The current condition and latest check are read from <code>status.json</code>.</p><p>The source files are publicly linked and can be downloaded without registration. The code does not insert hidden estimates or fill missing observations. If a row lacks a category, it is shown as unknown rather than assigned to the most likely group.</p><h2>Limitations that must be respected</h2><p>This report does not prove how many vessels crossed, how much oil moved or how long a physical interruption lasted. It also does not independently establish the accuracy of every news item. It is an editorial dataset describing decisions published by the monitor. Its value lies in traceability and in enabling outside review of the classification process.</p>""")
    updated=esc(status.get("checked_at")); current=esc(status.get("operational_label_es" if es else "operational_label_en"))
    schema=json.dumps({"@context":"https://schema.org","@type":"Dataset","name":title,"description":desc,"url":DOMAIN+("/datos-propios-monitor-ormuz.html" if es else "/en-monitor-original-data-report.html"),"dateModified":datetime.now(timezone.utc).date().isoformat(),"creator":{"@type":"Organization","name":"Estrecho Ormuz Editorial Team"},"distribution":{"@type":"DataDownload","encodingFormat":"application/json","contentUrl":DOMAIN+"/history.json"}},ensure_ascii=False,separators=(",",":"))
    return f'''<!DOCTYPE html><html lang="{lang}"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>{title} | Estrecho Ormuz</title><meta name="description" content="{desc}"/><link rel="canonical" href="{DOMAIN}/{'datos-propios-monitor-ormuz.html' if es else 'en-monitor-original-data-report.html'}"/><link rel="alternate" hreflang="{'en' if es else 'es'}" href="{DOMAIN}/{'en-monitor-original-data-report.html' if es else 'datos-propios-monitor-ormuz.html'}"/><link rel="stylesheet" href="/styles.css"/><link rel="stylesheet" href="/v11.css"/><link rel="stylesheet" href="/authority-v6.css"/><script type="application/ld+json">{schema}</script></head><body>{nav}<main class="site-main"><header class="a6-hero"><span class="section-kicker">{'Dataset propio' if es else 'Original dataset'}</span><h1>{title}</h1><p class="a6-deck">{desc}</p><div class="a6-meta"><span>{'Periodo' if es else 'Period'}: {first} → {last}</span><span>{'Última comprobación' if es else 'Last check'}: {updated}</span><span>{'Estado actual' if es else 'Current status'}: {current}</span></div></header><div class="a6-body"><div class="a6-summary">{cards}</div>{chart}<div class="a6-keybox"><strong>{'Cómo leerlo:' if es else 'How to read it:'}</strong> {note}</div>{interpretation}<h2>{'Categorías operativas' if es else 'Operational categories'}</h2><div class="a6-table-wrap"><table class="a6-table"><thead><tr><th>{'Categoría' if es else 'Category'}</th><th>{'Entradas' if es else 'Entries'}</th><th>{'Proporción' if es else 'Share'}</th></tr></thead><tbody>{op_rows}</tbody></table></div><h2>{'Confianza publicada' if es else 'Published confidence'}</h2><div class="a6-table-wrap"><table class="a6-table"><thead><tr><th>{'Nivel' if es else 'Level'}</th><th>{'Entradas' if es else 'Entries'}</th><th>{'Proporción' if es else 'Share'}</th></tr></thead><tbody>{conf_rows}</tbody></table></div><section class="a6-method"><h2>{'Método y limitaciones' if es else 'Method and limitations'}</h2><p>{method}</p><p><a href="/history.json">history.json</a> · <a href="/status.json">status.json</a> · <a href="/metodologia.html">{'Metodología' if es else 'Methodology'}</a></p></section></div></main></body></html>'''

def build_reports(root:Path|str|None=None):
    r=Path(root) if root else Path(__file__).resolve().parent
    (r/"datos-propios-monitor-ormuz.html").write_text(build(r,"es"),encoding="utf-8")
    (r/"en-monitor-original-data-report.html").write_text(build(r,"en"),encoding="utf-8")

if __name__=="__main__":build_reports()
